package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A hold on a person, from its from-date (null: the beginning of time) to its to-date (null: no end), both inclusive. */
public record Hold(LocalDate from, LocalDate to) {

    /** Whether the date falls within the hold. */
    public boolean covers(LocalDate date) {
        return (from == null || !date.isBefore(from)) && (to == null || !date.isAfter(to));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Adds a hold to the person, from the date given (blank: the sheet's today) to its to-date (blank: no end); a
 * to-date before the from-date is refused (400).
 */
public class HoldPerson {
    public void hold(@Val Person person, @Val Hold hold, PersonRepository people, SheetRepository sheets,
            Out<Person> updated) throws InvalidPersonException {
        Hold dated = hold.from() != null ? hold : new Hold(sheets.today(person.sheetId()), hold.to());
        if (dated.to() != null && dated.to().isBefore(dated.from())) {
            throw new InvalidPersonException("A hold's to-date must not be before its from-date.");
        }
        updated.set(people.hold(person, dated));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the hold just added to the person (their last), by its from-date. */
public class AuditPersonHeld {
    public void audit(@Val Person person, @RequestParam("user") String user, Audit audit) {
        Hold hold = person.holds().get(person.holds().size() - 1);
        audit.record("PERSON_HELD sheet=" + person.sheetId() + " by=" + user + " name=" + person.name() + " from="
                + hold.from());
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Refuses (400) a hold whose dates are not yyyy-mm-dd; a blank from-date is the sheet's today (null here), a blank
 * to-date no end.
 */
public class ValidateHoldRequest {
    public void validate(@RequestBody @Valid HoldRequest request, Out<Hold> hold) throws InvalidPersonException {
        LocalDate from = date(request.from());
        LocalDate to = date(request.to());
        hold.set(new Hold(from, to));
    }

    private static LocalDate date(String value) throws InvalidPersonException {
        String text = value == null ? "" : value.trim();
        if (text.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("A hold's dates must be yyyy-mm-dd.");
        }
    }
}
