set -e
R=../../../../../resources/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}
cat > "$R/hold.POST.yml" <<'EOF'
# Toggle an OPEN or PENDING claim's hold: holding writes CLAIM_HELD, releasing CLAIM_RELEASED. A held claim leaves the
# live totals as a hold on its person would (a figure bound by a statement stays in). Any other status is refused (400)
# and writes nothing.
